/// Native replay implementations for device bindings.
#[inline]
fn destack_device_bluetooth_adapter_list_replay(
    context: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeSlice<BluetoothAdapterDescriptor>,
) -> RuntimeResult<()> {
    context.replay().run_binding_with_policy(
        DEVICE_BLUETOOTH_ADAPTER_LIST,
        context.replay_payload_for(DEVICE_BLUETOOTH_ADAPTER_LIST)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_device_bluetooth_adapter_list(context, out)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_device_bluetooth_adapter_list(context, out)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded_raw = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item = *result_recorded_item_value;
                    let result_recorded_item_recorded_id =
                        unsafe { result_recorded_item.id.as_str()? }.to_string();
                    let result_recorded_item_recorded_name =
                        unsafe { result_recorded_item.name.as_str()? }.to_string();
                    let result_recorded_item_recorded_powered = result_recorded_item.powered;
                    let result_recorded_item_recorded_low_energy = result_recorded_item.low_energy;
                    let result_recorded_item_recorded = BluetoothAdapterDescriptorReplayRecord {
                        id: result_recorded_item_recorded_id,
                        name: result_recorded_item_recorded_name,
                        powered: result_recorded_item_recorded_powered,
                        low_energy: result_recorded_item_recorded_low_energy,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = DeviceBluetoothAdapterListReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    DeviceBluetoothAdapterListReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut value_native_values = Vec::with_capacity(value.len());
                    for value_native_item in value {
                        let value_native_item_native_id =
                            context.store_string(&value_native_item.id);
                        let value_native_item_native_name =
                            context.store_string(&value_native_item.name);
                        let value_native_item_native_powered = value_native_item.powered;
                        let value_native_item_native_low_energy = value_native_item.low_energy;
                        let value_native_item_native = BluetoothAdapterDescriptor {
                            id: value_native_item_native_id,
                            name: value_native_item_native_name,
                            powered: value_native_item_native_powered,
                            low_energy: value_native_item_native_low_energy,
                        };
                        value_native_values.push(value_native_item_native);
                    }
                    let value_native = context.store_slice(value_native_values);
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

