/// VM replay implementations for device bindings.
#[inline]
fn destack_device_bluetooth_adapter_list_vm_replay(
    runtime: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
) -> RuntimeResult<vm::Value> {
    let result = runtime.replay().run_binding_with_context_policy(
        DEVICE_BLUETOOTH_ADAPTER_LIST,
        runtime.replay_payload_for(DEVICE_BLUETOOTH_ADAPTER_LIST)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_device_bluetooth_adapter_list(runtime, context)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_device_bluetooth_adapter_list(runtime, context)
            }
        },
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value: VmSlice<BluetoothAdapterDescriptorVm> = value.clone();
                let result_recorded_raw = result_value.raw_values(context)?;
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item = {
                        if result_recorded_item_value.tag() != vm::ValueTag::Aggregate {
                            return Err(RuntimeError::from(PlatformError::invalid_argument_type(
                                "result_recorded_item",
                                "item",
                            ))
                            .boxed());
                        }
                        let slots = context
                            .aggregate_slots(result_recorded_item_value)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        if slots.len() != 4 {
                            return Err(RuntimeError::from(PlatformError::invalid_argument_value(
                                "result_recorded_item",
                                "expected 4 fields",
                            ))
                            .boxed());
                        }
                        let result_recorded_item_id =
                            decode_string(slots[0], "result_recorded_item_id", "id")?;
                        let result_recorded_item_name =
                            decode_string(slots[1], "result_recorded_item_name", "name")?;
                        let result_recorded_item_powered =
                            decode_bool(slots[2], "result_recorded_item_powered", "powered")?;
                        let result_recorded_item_low_energy =
                            decode_bool(slots[3], "result_recorded_item_low_energy", "lowEnergy")?;
                        BluetoothAdapterDescriptorVm {
                            id: result_recorded_item_id,
                            name: result_recorded_item_name,
                            powered: result_recorded_item_powered,
                            low_energy: result_recorded_item_low_energy,
                        }
                    };
                    let result_recorded_item_recorded_id = {
                        let result_recorded_item_recorded_id_ref = context
                            .string_ref(result_recorded_item.id)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        result_recorded_item_recorded_id_ref.as_str().to_string()
                    };
                    let result_recorded_item_recorded_name = {
                        let result_recorded_item_recorded_name_ref = context
                            .string_ref(result_recorded_item.name)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        result_recorded_item_recorded_name_ref.as_str().to_string()
                    };
                    let result_recorded_item_recorded_powered = result_recorded_item.powered;
                    let result_recorded_item_recorded_low_energy = result_recorded_item.low_energy;
                    let result_recorded_item_recorded = BluetoothAdapterDescriptorReplayRecord {
                        id: result_recorded_item_recorded_id,
                        name: result_recorded_item_recorded_name,
                        powered: result_recorded_item_recorded_powered,
                        low_energy: result_recorded_item_recorded_low_energy,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = DeviceBluetoothAdapterListReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    DeviceBluetoothAdapterListReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_values = Vec::with_capacity(value.len());
                    for vm_result_item in value.iter() {
                        let vm_result_item = vm_result_item.clone();
                        let vm_result_item_value_id_value =
                            context.intern_string(vm_result_item.id.as_str());
                        let vm_result_item_value_id =
                            vm::StringHandle::new(vm_result_item_value_id_value);
                        let vm_result_item_value_name_value =
                            context.intern_string(vm_result_item.name.as_str());
                        let vm_result_item_value_name =
                            vm::StringHandle::new(vm_result_item_value_name_value);
                        let vm_result_item_value_powered = vm_result_item.powered;
                        let vm_result_item_value_low_energy = vm_result_item.low_energy;
                        let vm_result_item_value = BluetoothAdapterDescriptorVm {
                            id: vm_result_item_value_id,
                            name: vm_result_item_value_name,
                            powered: vm_result_item_value_powered,
                            low_energy: vm_result_item_value_low_energy,
                        };
                        let vm_result_item_value_encoded = {
                            let field_0 = vm_result_item_value.id.value();
                            let field_1 = vm_result_item_value.name.value();
                            let field_2 = vm::Value::bool(vm_result_item_value.powered);
                            let field_3 = vm::Value::bool(vm_result_item_value.low_energy);
                            context.allocate_aggregate(vec![field_0, field_1, field_2, field_3])
                        };
                        vm_result_values.push(vm_result_item_value_encoded);
                    }
                    let vm_result_data = context.allocate_raw_values(vm_result_values);
                    let vm_result: VmSlice<BluetoothAdapterDescriptorVm> = VmSlice {
                        data: vm_result_data,
                        len: value.len() as u32,
                        _marker: std::marker::PhantomData,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    );
    let result = encode_destack_device_bluetooth_adapter_list_result(context, result)?;
    Ok(result)
}

