#[inline]
fn destack_device_usb_string_language_list_vm_replay(
    runtime: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::UsbDeviceHandle,
) -> RuntimeResult<vm::Value> {
    let result = runtime.replay().run_binding_with_context_policy(
        DEVICE_USB_STRING_LANGUAGE_LIST,
        runtime.replay_payload_for(DEVICE_USB_STRING_LANGUAGE_LIST)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_device_usb_string_language_list(runtime, context, handle)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_device_usb_string_language_list(
                    runtime, context, handle,
                )
            }
        },
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value: VmSlice<u16> = value.clone();
                let result_recorded_raw = result_value.raw_values(context)?;
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item =
                        decode_uint16(result_recorded_item_value, "result_recorded_item", "item")?;
                    let result_recorded_item_recorded = result_recorded_item;
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = DeviceUsbStringLanguageListReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    DeviceUsbStringLanguageListReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_values = Vec::with_capacity(value.len());
                    for vm_result_item in value.iter() {
                        let vm_result_item = *vm_result_item;
                        let vm_result_item_value = vm_result_item;
                        vm_result_values.push(vm_result_item_value);
                    }
                    let vm_result = VmSlice::from_values(context, &vm_result_values)?;
                    Ok(vm_result)
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    );
    let result = encode_destack_device_usb_string_language_list_result(context, result)?;
    Ok(result)
}

